"""tables.md from runs/*/seed*/log.json and battery_*.json (bump reward).

    .venv/bin/python studies/8_language_models/bump_reward/tables.py
"""

from __future__ import annotations

import json
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent
ci = lambda x: f"{x[0]:.2f}–{x[1]:.2f}"


def main():
    logs = {}
    for p in sorted(HERE.glob("runs/*/seed*/log.json")):
        d = json.loads(p.read_text()); logs.setdefault(d["kind"], {})[d["seed"]] = d["log"]
    bats = {p.stem.replace("battery_", ""): json.loads(p.read_text()) for p in sorted(HERE.glob("battery_*.json"))}
    L = ["# Bump reward: tables", "", "Generated by `tables.py`. PPO on reward only, the single-goal bump maze; the exact optimum returns 0.512 with success 0.995, QMDP 0, random 0.057, wall-follower 0.083; the supervised transformer 0.468 / 0.887, the supervised GRU 0.508 / 0.979.", ""]
    L += ["## Training (greedy on the 2 048 fixed test starts)", "", "| architecture | seed | final return | success | length | return at update 250 / 500 / 1000 | episodes |", "|---|---|---|---|---|---|---|"]
    med = {}
    for kind, seeds in logs.items():
        finals = {s: lg[-1] for s, lg in seeds.items()}; order = sorted(finals, key=lambda s: finals[s]["ret"]); med[kind] = order[len(order) // 2]
        for s in sorted(seeds):
            lg = seeds[s]; at = {u: next((r["ret"] for r in lg if r["update"] == u), float("nan")) for u in (250, 500, 1000)}
            L.append(f"| {kind} | {s}{' (median)' if s == med[kind] else ''} | {finals[s]['ret']:.3f} | {finals[s]['success']:.3f} | {finals[s]['length']:.1f} | {at[250]:.3f} / {at[500]:.3f} / {at[1000]:.3f} | {finals[s]['interactions'] / 1e6:.1f} M steps |")
        rets = [finals[s]["ret"] for s in seeds]; L.append(f"| {kind} | mean over seeds | {np.mean(rets):.3f} ({min(rets):.3f}–{max(rets):.3f}) | {np.mean([finals[s]['success'] for s in seeds]):.3f} | | | |")
    L.append("")
    if bats:
        L += ["## The battery", "", "### A. The table over all reachable sets and set-sufficiency", "", "| model | online greedy return | own coverage (sets) | all sets optimal | optimum-visited | imitation-visited, not by the optimum | never visited by the imitation data | visited by the agent's own episodes | never visited by the agent | set-sufficiency (baseline) | table value from the start: of V* / of the online return | mean V^π / V* | lost |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
        for name, b in bats.items():
            t = b["table"]; g = [t[k] for k in ("optimum-visited", "imitation-training-visited, not by the optimum", "never visited by the imitation data", "visited by the agent's own episodes", "never visited by the agent")]; s = b["sufficiency"]["all"]; v = b["value_shortest"]
            L.append(f"| {name} | {b['online']['ret']:.3f} ({b['online']['success']:.2f}) | {b['own_coverage_sets']} | {t['all']['optimal']:.3f} | " + " | ".join(f"{x['optimal']:.3f} ({x['n']})" for x in g) + f" | {s['same']:.3f} ({ci(s['same_ci'])}; {s['baseline_same_size']:.2f}) | {v['start_ratio']:.3f} / {v['vs_online']:.3f} | {v['mean_ratio_all']:.3f} | {v['lost']:.3f} |")
        L += ["", "### B1. Probes at the decision position, uniform over sets, held out by set (residual entering each block; the last row the final residual; GRU: the hidden state)", "", "| model | block | set exact | Jaccard | Q* R² | P(bump) R² |", "|---|---|---|---|---|---|"]
        for name, b in bats.items():
            for r in b["probes"]: L.append(f"| {name} | {r['layer']} | {r['set_exact']:.3f} | {r['set_jaccard']:.2f} | {r['Q_r2']:.3f} | {r['pbump_r2']:.3f} |")
        L += ["", "### C1. Swaps of the decision position's residual (1 024 same-set pairs, 1 024 different-set pairs of the same size)", "", "| model | block | same set: decision changed | same set, where the decisions differ: to the donor's | different sets: to the donor's | natural disagreement same / different |", "|---|---|---|---|---|---|"]
        for name, b in bats.items():
            sw = b["swaps"]
            for r in sw["layers"]: L.append(f"| {name} | {r['layer']} | {r['same_changed']:.3f} ({ci(r['same_changed_ci'])}) | {r['same_to_donor'] if r['same_to_donor'] is None else round(r['same_to_donor'], 3)} | {r['diff_to_donor']:.3f} ({ci(r['diff_to_donor_ci'])}) | {sw['same_natural_disagree']:.2f} / {sw['diff_natural_disagree']:.2f} |")
        L += ["", "### D2. The prefix patch (transformers)", "", "| model | block | last prefix token ← B: to B's decision | all prefix tokens | middle token | pairs (natural differ) |", "|---|---|---|---|---|---|"]
        for name, b in bats.items():
            if "prefix" in b:
                for r in b["prefix"]["layers"]: L.append(f"| {name} | {r['layer']} | {r['last_prefix_token']['to_B']:.3f} ({ci(r['last_prefix_token']['to_B_ci'])}) | {r['all_prefix_tokens']['to_B']:.3f} | {r['middle_prefix_token']['to_B']:.3f} | {b['prefix']['n_pairs']} ({b['prefix']['natural_differ']:.2f}) |")
        L.append("")
        # scorecard on the median seeds
        L += ["## Scorecard (the median-return seed of each architecture)", "", "| | criterion | transformer | GRU |", "|---|---|---|---|"]
        def pick(kind):
            s = med.get(kind); return bats.get(f"ppo_{kind}_seed{s}") if s is not None else None
        bt, bg = pick("tfm"), pick("gru")
        def cell(b, f):
            try: return f(b) if b else "–"
            except Exception: return "–"
        L.append("| LEARN | return ≥ 0.30, success ≥ 0.60 | " + " | ".join(cell(b, lambda b: f"{b['online']['ret']:.3f} / {b['online']['success']:.3f}: {'yes' if b['online']['ret'] >= 0.30 and b['online']['success'] >= 0.60 else 'no'}") for b in (bt, bg)) + " |")
        L.append("| SUF-R | set-sufficiency ≥ 0.70 and ≥ 0.15 above baseline | " + " | ".join(cell(b, lambda b: f"{b['sufficiency']['all']['same']:.3f} ({ci(b['sufficiency']['all']['same_ci'])}; baseline {b['sufficiency']['all']['baseline_same_size']:.2f}): {'yes' if b['sufficiency']['all']['same_ci'][0] >= 0.70 and b['sufficiency']['all']['same'] - b['sufficiency']['all']['baseline_same_size'] >= 0.15 else 'no'}") for b in (bt, bg)) + " |")
        L.append("| OUT-R | optimal on sets the imitation data never visits ≥ 0.60 | " + " | ".join(cell(b, lambda b: f"{b['table']['never visited by the imitation data']['optimal']:.3f} ({ci(b['table']['never visited by the imitation data']['optimal_ci'])}): {'yes' if b['table']['never visited by the imitation data']['optimal_ci'][0] >= 0.60 else 'no'}") for b in (bt, bg)) + " |")
        L.append("| VALUE-R | table value within 5 % of the online return | " + " | ".join(cell(b, lambda b: f"{b['value_shortest']['vs_online']:.3f}: {'yes' if abs(b['value_shortest']['vs_online'] - 1) <= 0.05 else 'no'}") for b in (bt, bg)) + " |")
        L.append("| CODE-R | set exact ≤ 0.10 at every block; P(bump) R² ≥ 0.60 somewhere | " + " | ".join(cell(b, lambda b: f"max exact {max(r['set_exact'] for r in b['probes']):.3f}, max P(bump) {max(r['pbump_r2'] for r in b['probes']):.2f}: {'yes' if max(r['set_exact'] for r in b['probes']) <= 0.10 and max(r['pbump_r2'] for r in b['probes']) >= 0.60 else 'no'}") for b in (bt, bg)) + " |")
        L.append("| SAME-R | same-set swaps change ≤ 0.10 at every block | " + " | ".join(cell(b, lambda b: f"max {max(r['same_changed'] for r in b['swaps']['layers']):.3f}: {'yes' if max(r['same_changed_ci'][1] for r in b['swaps']['layers']) <= 0.10 else 'no'}") for b in (bt, bg)) + " |")
        L.append("| PRIOR-R | last prefix token ≤ 0.10 at every block; all prefix tokens ≥ 0.80 at block 0 | " + cell(bt, lambda b: f"max last {max(r['last_prefix_token']['to_B'] for r in b['prefix']['layers']):.3f}, all at 0: {b['prefix']['layers'][0]['all_prefix_tokens']['to_B']:.3f}: {'yes' if max(r['last_prefix_token']['to_B_ci'][1] for r in b['prefix']['layers']) <= 0.10 and b['prefix']['layers'][0]['all_prefix_tokens']['to_B'] >= 0.80 else 'no'}") + " | not run (recurrent) |")
    Path(HERE, "tables.md").write_text("\n".join(L) + "\n"); print("\n".join(L))


if __name__ == "__main__":
    main()
